// Mirrors the test's shape: wrapper writes exit file at pipeline exit;
// tail message written by the wizard just before exiting.
Future<void> main(List<String> args) async {
  final iterations = int.parse(args[0]);
  final waitForDone = args[1] == 'fix'; // 'fix' = new awaitExit behavior
  final tmp = await Directory.systemTemp.createTemp('ptyprobe_');
  var lost = 0, ok = 0, neverDrained = 0;
  for (var i = 0; i < iterations; i++) {
    final exitFile = '${tmp.path}/exit_$i';
    final script = File('${tmp.path}/wiz_$i.sh')
      ..writeAsStringSync('''
printf 'Reconfigure? [y/N] '
sleep 0.12
printf 'Kept existing config.\\n'
''');
    final buffer = StringBuffer();
    var done = false;
    final pty = PseudoTerminal.start(
      'dash',
      ['-c', 'cat "\$1" | dash; echo \$? > "\$2"', 'w', script.path, exitFile],
      workingDirectory: tmp.path,
      environment: {'HOME': tmp.path, 'PATH': Platform.environment['PATH']!},
      raw: false,
    );
    pty.out.listen(buffer.write, onDone: () => done = true);
    final sw = Stopwatch()..start();
    var code = -999;
    while (sw.elapsed < const Duration(seconds: 10)) {
      final f = File(exitFile);
      if (f.existsSync()) {
        final t = f.readAsStringSync().trim();
        if (t.isNotEmpty) {
          code = int.parse(t);
          if (waitForDone) {
            while (!done && sw.elapsed < const Duration(seconds: 10)) {
              await Future<void>.delayed(const Duration(milliseconds: 10));
            }
            if (!done) neverDrained++;
          }
          break;
        }
      }
      await Future<void>.delayed(const Duration(milliseconds: 30));
    }
    final lostTail = !buffer.toString().contains('Kept existing config.');
    if (lostTail) {
      lost++;
      if (lostTail && ok == 0 && lost == 1) {
        stderr.writeln('FIRST LOSS captured (mode=$waitForDone): '
            'buffer=[${buffer.toString().replaceAll('\n', '|')}] code=$code done=$done');
      }
    } else {
      ok++;
    }
    pty.kill();
    try { await pty.exitCode; } catch (_) {}
  }
  await tmp.delete(recursive: true);
  stdout.writeln('mode=${waitForDone ? "fix(done-wait)" : "old(no-wait)"} '
      'iters=$iterations ok=$ok LOST=$lost neverDrained=$neverDrained');
}
EOF
