import 'dart:io';
import 'package:pty2/pty2.dart';

// Old behavior + post-mortem: on tail loss, keep waiting for done and re-check.
// Tail appears after done -> loss was main-isolate delivery lag (fix heals it).
// Tail never appears -> kernel discarded at close (fix cannot heal).
Future<void> main(List<String> args) async {
  final iterations = int.parse(args[0]);
  final tmp = await Directory.systemTemp.createTemp('ptyprobe2_');
  var lost = 0, recoveredAfterDone = 0, permanentLoss = 0;
  for (var i = 0; i < iterations; i++) {
    final exitFile = '${tmp.path}/exit_$i';
    final script = File('${tmp.path}/wiz_$i.sh')
      ..writeAsStringSync('''
printf 'Reconfigure? [y/N] '
sleep 0.12
printf 'Kept existing config.\\n'
''');
    final buffer = StringBuffer();
    var done = false;
    final pty = PseudoTerminal.start(
      'dash',
      ['-c', 'cat "\$1" | dash; echo \$? > "\$2"', 'w', script.path, exitFile],
      workingDirectory: tmp.path,
      environment: {'HOME': tmp.path, 'PATH': Platform.environment['PATH']!},
      raw: false,
    );
    pty.out.listen(buffer.write, onDone: () => done = true);
    final sw = Stopwatch()..start();
    while (sw.elapsed < const Duration(seconds: 10)) {
      final f = File(exitFile);
      if (f.existsSync() && f.readAsStringSync().trim().isNotEmpty) break;
      await Future<void>.delayed(const Duration(milliseconds: 30));
    }
    var lostHere = !buffer.toString().contains('Kept existing config.');
    if (lostHere) {
      lost++;
      // post-mortem: wait for done, then re-check
      while (!done && sw.elapsed < const Duration(seconds: 10)) {
        await Future<void>.delayed(const Duration(milliseconds: 10));
      }
      if (buffer.toString().contains('Kept existing config.')) {
        recoveredAfterDone++;
        stdout.writeln('iter $i: loss at file-observation, tail ARRIVED after done '
          '(delivery lag; done-wait heals) doneAt=${sw.elapsedMilliseconds}ms');
      } else {
        permanentLoss++;
        stdout.writeln('iter $i: tail NEVER arrived even after done '
          '(kernel discard at close; done-wait CANNOT heal)');
      }
    }
    pty.kill();
    try { await pty.exitCode; } catch (_) {}
  }
  await tmp.delete(recursive: true);
  stdout.writeln('iters=$iterations losses=$lost recoveredAfterDone=$recoveredAfterDone permanentLoss=$permanentLoss');
}
EOF
